    12  /* Decode a message, then encode, decode, encode.
    13   * The two encodings must be bit-equal. */
    14  extern "C" int
    15  LLVMFuzzerTestOneInput(uint8_t *data, size_t size) {
    16      UA_ByteString buf;
    17      buf.data = (UA_Byte*)data;
    18      buf.length = size;
    19
    20      UA_Variant value;
    21      UA_Variant_init(&value);
    22
    23      UA_StatusCode retval = UA_decodeJson(&buf, &value, &UA_TYPES[UA_TYPES_VARIANT]);
    24      if(retval != UA_STATUSCODE_GOOD)
    25          return 0;
    26
    27      size_t jsonSize = UA_calcSizeJson(&value, &UA_TYPES[UA_TYPES_VARIANT],
    28                                        NULL, 0, NULL, 0, true);
    29
    30      UA_ByteString buf2 = UA_BYTESTRING_NULL;
    31      retval = UA_ByteString_allocBuffer(&buf2, jsonSize);
    32      if(retval != UA_STATUSCODE_GOOD) {
    33          UA_Variant_deleteMembers(&value);
    34          return 0;
    35      }
    36
    37      uint8_t *bufPos = buf2.data;
    38      const uint8_t *bufEnd = &buf2.data[buf2.length];
    39      retval = UA_encodeJson(&value, &UA_TYPES[UA_TYPES_VARIANT],
    40                             &bufPos, &bufEnd, NULL, 0, NULL, 0, true);
    41          UA_Variant_deleteMembers(&value);
    42          if(retval != UA_STATUSCODE_GOOD || bufPos != bufEnd) {
    43               return 0;
    44          }
    45
    46      UA_Variant value2;
    47      UA_Variant_init(&value2);
    48
    49      retval = UA_decodeJson(&buf2, &value2, &UA_TYPES[UA_TYPES_VARIANT]);
    50      if(retval != UA_STATUSCODE_GOOD) {
    51               return 0;
    52          }
    53
    54      UA_ByteString buf3 = UA_BYTESTRING_NULL;
    55      retval = UA_ByteString_allocBuffer(&buf3, jsonSize);
    56      if(retval != UA_STATUSCODE_GOOD) {
    57          UA_Variant_deleteMembers(&value2);
    58          UA_ByteString_deleteMembers(&buf2);
    59          return 0;
    60      }
    61
    62      bufPos = buf3.data;
    63      bufEnd = &buf3.data[buf3.length];
    64      retval = UA_encodeJson(&value2, &UA_TYPES[UA_TYPES_VARIANT],
    65                             &bufPos, &bufEnd, NULL, 0, NULL, 0, true);
    66          UA_Variant_deleteMembers(&value2);
    67          if(retval != UA_STATUSCODE_GOOD) {
    68               UA_ByteString_deleteMembers(&buf2);
    69               UA_ByteString_deleteMembers(&buf3);
    70               return 0;
    71          }
    72      if (memcmp(buf2.data, buf3.data, buf.length) != 0) {
    73          // ignore
    74      }
    75
    76      UA_ByteString_deleteMembers(&buf2);
    77      UA_ByteString_deleteMembers(&buf3);
    78
    79      return 0;
    80  }
